UPDATE "Lead" l SET
  status = CASE
    WHEN status IN ('sourced','enriching','enriched','skipped') THEN 'enriched'
    WHEN status = 'scored' AND FALSE THEN 'skipped'
    ELSE status
  END,
  "notes" = CASE
    WHEN status IN ('sourced','enriching','enriched','skipped') THEN 'Účtáreň kth.sk; info@kth.sk na webe; účto, mzdy, poradenstvo.'
    WHEN status = 'scored' AND FALSE THEN 'Účtáreň kth.sk; info@kth.sk na webe; účto, mzdy, poradenstvo.'
    ELSE "notes"
  END,
  "skipReason" = CASE
    WHEN status IN ('sourced','enriching','enriched','skipped') THEN NULL
    WHEN status = 'scored' AND FALSE THEN NULL
    ELSE "skipReason"
  END,
  "updatedAt" = NOW()
FROM "Company" c
WHERE l."companyId" = c.id AND c.ico = '47998334';
